     2→// SPDX-License-Identifier: LGPL-3.0-only
     3→
     4→using System;
     5→using Nethermind.Consensus.Messages;
     6→using Nethermind.Core;
     7→using Nethermind.Core.Specs;
     8→using Nethermind.TxPool;
     9→using Nethermind.Core.Crypto;
    10→using Nethermind.Crypto;
    11→using Nethermind.Evm;
    12→using Nethermind.Int256;
    13→
    14→namespace Nethermind.Consensus.Validators;
    15→
    16→public sealed class TxValidator : ITxValidator
    17→{
    18→    private readonly ITxValidator?[] _validators = new ITxValidator?[Transaction.MaxTxType + 1];
    19→
    20→    public TxValidator(ulong chainId)
    21→    {
    22→        RegisterValidator(TxType.Legacy, new CompositeTxValidator([
    23→            IntrinsicGasTxValidator.Instance,
    24→            new LegacySignatureTxValidator(chainId),
    25→            ContractSizeTxValidator.Instance,
    26→            NonBlobFieldsTxValidator.Instance,
    27→            NonSetCodeFieldsTxValidator.Instance,
    28→            GasLimitCapTxValidator.Instance
    29→        ]));
    30→
    31→        var expectedChainIdTxValidator = new ExpectedChainIdTxValidator(chainId);
    32→        RegisterValidator(TxType.AccessList, new CompositeTxValidator([
    33→            new ReleaseSpecTxValidator(static spec => spec.IsEip2930Enabled),
    34→            IntrinsicGasTxValidator.Instance,
    35→            SignatureTxValidator.Instance,
    36→            expectedChainIdTxValidator,
    37→            ContractSizeTxValidator.Instance,
    38→            NonBlobFieldsTxValidator.Instance,
    39→            NonSetCodeFieldsTxValidator.Instance,
    40→            GasLimitCapTxValidator.Instance
    41→        ]));
    42→        RegisterValidator(TxType.EIP1559, new CompositeTxValidator([
    43→            new ReleaseSpecTxValidator(static spec => spec.IsEip1559Enabled),
    44→            IntrinsicGasTxValidator.Instance,
    45→            SignatureTxValidator.Instance,
    46→            expectedChainIdTxValidator,
    47→            GasFieldsTxValidator.Instance,
    48→            ContractSizeTxValidator.Instance,
    49→            NonBlobFieldsTxValidator.Instance,
    50→            NonSetCodeFieldsTxValidator.Instance,
    51→            GasLimitCapTxValidator.Instance
    52→        ]));
    53→        RegisterValidator(TxType.Blob, new CompositeTxValidator([
    54→            new ReleaseSpecTxValidator(static spec => spec.IsEip4844Enabled),
    55→            IntrinsicGasTxValidator.Instance,
    56→            SignatureTxValidator.Instance,
    57→            expectedChainIdTxValidator,
    58→            GasFieldsTxValidator.Instance,
    59→            ContractSizeTxValidator.Instance,
    60→            BlobFieldsTxValidator.Instance,
    61→            MempoolBlobTxValidator.Instance,
    62→            MempoolBlobTxProofVersionValidator.Instance,
    63→            NonSetCodeFieldsTxValidator.Instance,
    64→            GasLimitCapTxValidator.Instance
    65→        ]));
    66→        RegisterValidator(TxType.SetCode, new CompositeTxValidator([
    67→            new ReleaseSpecTxValidator(static spec => spec.IsEip7702Enabled),
    68→            IntrinsicGasTxValidator.Instance,
    69→            SignatureTxValidator.Instance,
    70→            expectedChainIdTxValidator,
    71→            GasFieldsTxValidator.Instance,
    72→            ContractSizeTxValidator.Instance,
    73→            NonBlobFieldsTxValidator.Instance,
    74→            NoContractCreationTxValidator.Instance,
    75→            AuthorizationListTxValidator.Instance,
    76→            GasLimitCapTxValidator.Instance
    77→        ]));
    78→    }
    79→
    80→    public void RegisterValidator(TxType type, ITxValidator validator) => _validators[(byte)type] = validator;
    81→
    82→    /// <remarks>
    83→    /// Full and correct validation is only possible in the context of a specific block
    84→    /// as we cannot generalize correctness of the transaction without knowing the EIPs implemented
    85→    /// and the world state(account nonce in particular).
    86→    /// Even without protocol change, the tx can become invalid if another tx
    87→    /// from the same account with the same nonce got included on the chain.
    88→    /// As such, we can decide whether tx is well formed as long as we also validate nonce
    89→    /// just before the execution of the block / tx.
    90→    /// </remarks>
    91→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
    92→        _validators.TryGetByTxType(transaction.Type, out ITxValidator validator)
    93→            ? validator.IsWellFormed(transaction, releaseSpec)
    94→            : TxErrorMessages.InvalidTxType(releaseSpec.Name);
    95→}
    96→
    97→public class CompositeTxValidator(params ITxValidator[] validators) : ITxValidator
    98→{
    99→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   100→    {
   101→        foreach (ITxValidator validator in validators)
   102→        {
   103→            ValidationResult isWellFormed = validator.IsWellFormed(transaction, releaseSpec);
   104→            if (!isWellFormed)
   105→            {
   106→                return isWellFormed;
   107→            }
   108→        }
   109→
   110→        return ValidationResult.Success;
   111→    }
   112→}
   113→
   114→public sealed class IntrinsicGasTxValidator : ITxValidator
   115→{
   116→    public static readonly IntrinsicGasTxValidator Instance = new();
   117→    private IntrinsicGasTxValidator() { }
   118→
   119→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   120→    {
   121→        // This is unnecessarily calculated twice - at validation and execution times.
   122→        IntrinsicGas intrinsicGas = IntrinsicGasCalculator.Calculate(transaction, releaseSpec);
   123→        return transaction.GasLimit < intrinsicGas.MinimalGas
   124→            ? TxErrorMessages.IntrinsicGasTooLow
   125→            : ValidationResult.Success;
   126→    }
   127→}
   128→
   129→public sealed class ReleaseSpecTxValidator(Func<IReleaseSpec, bool> validate) : ITxValidator
   130→{
   131→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   132→        !validate(releaseSpec) ? TxErrorMessages.InvalidTxType(releaseSpec.Name) : ValidationResult.Success;
   133→}
   134→
   135→public sealed class ExpectedChainIdTxValidator(ulong chainId) : ITxValidator
   136→{
   137→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   138→        transaction.ChainId != chainId ? TxErrorMessages.InvalidTxChainId(chainId, transaction.ChainId) : ValidationResult.Success;
   139→}
   140→
   141→public sealed class GasFieldsTxValidator : ITxValidator
   142→{
   143→    public static readonly GasFieldsTxValidator Instance = new();
   144→    private GasFieldsTxValidator() { }
   145→
   146→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   147→        transaction.MaxFeePerGas < transaction.MaxPriorityFeePerGas ? TxErrorMessages.InvalidMaxPriorityFeePerGas : ValidationResult.Success;
   148→}
   149→
   150→public sealed class ContractSizeTxValidator : ITxValidator
   151→{
   152→    public static readonly ContractSizeTxValidator Instance = new();
   153→    private ContractSizeTxValidator() { }
   154→
   155→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   156→        transaction.IsAboveInitCode(releaseSpec) ? TxErrorMessages.ContractSizeTooBig : ValidationResult.Success;
   157→}
   158→
   159→/// <remark>
   160→///  Ensure that non Blob transactions do not contain Blob specific fields.
   161→///  This validator will be deprecated once we have a proper Transaction type hierarchy.
   162→/// </remark>
   163→public sealed class NonBlobFieldsTxValidator : ITxValidator
   164→{
   165→    public static readonly NonBlobFieldsTxValidator Instance = new();
   166→    private NonBlobFieldsTxValidator() { }
   167→
   168→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) => transaction switch
   169→    {
   170→        // Execution-payload version verification
   171→        { MaxFeePerBlobGas: not null } => TxErrorMessages.NotAllowedMaxFeePerBlobGas,
   172→        { BlobVersionedHashes: not null } => TxErrorMessages.NotAllowedBlobVersionedHashes,
   173→        { NetworkWrapper: ShardBlobNetworkWrapper } => TxErrorMessages.InvalidTransactionForm,
   174→        _ => ValidationResult.Success
   175→    };
   176→}
   177→
   178→public sealed class NonSetCodeFieldsTxValidator : ITxValidator
   179→{
   180→    public static readonly NonSetCodeFieldsTxValidator Instance = new();
   181→    private NonSetCodeFieldsTxValidator() { }
   182→
   183→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) => transaction switch
   184→    {
   185→        { AuthorizationList: not null } => TxErrorMessages.NotAllowedAuthorizationList,
   186→        _ => ValidationResult.Success
   187→    };
   188→}
   189→
   190→public sealed class BlobFieldsTxValidator : ITxValidator
   191→{
   192→    public static readonly BlobFieldsTxValidator Instance = new();
   193→    private BlobFieldsTxValidator() { }
   194→
   195→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   196→        transaction switch
   197→        {
   198→            { To: null } => TxErrorMessages.TxMissingTo,
   199→            { MaxFeePerBlobGas: null } => TxErrorMessages.BlobTxMissingMaxFeePerBlobGas,
   200→            { BlobVersionedHashes: null } => TxErrorMessages.BlobTxMissingBlobVersionedHashes,
   201→            _ => ValidateBlobFields(transaction, releaseSpec)
   202→        };
   203→
   204→    private static ValidationResult ValidateBlobFields(Transaction transaction, IReleaseSpec spec)
   205→    {
   206→        int blobCount = transaction.BlobVersionedHashes!.Length;
   207→
   208→        ValidationResult blobPerTxLimitValidationResult = ValidateBlobGasLimits(blobCount, spec);
   209→
   210→        if (!blobPerTxLimitValidationResult)
   211→        {
   212→            return blobPerTxLimitValidationResult;
   213→        }
   214→
   215→        for (int i = 0; i < blobCount; i++)
   216→        {
   217→            switch (transaction.BlobVersionedHashes[i])
   218→            {
   219→                case null: return TxErrorMessages.MissingBlobVersionedHash;
   220→                case { Length: not KzgPolynomialCommitments.BytesPerBlobVersionedHash }: return TxErrorMessages.InvalidBlobVersionedHashSize;
   221→                case { Length: KzgPolynomialCommitments.BytesPerBlobVersionedHash } when transaction.BlobVersionedHashes[i][0] != KzgPolynomialCommitments.KzgBlobHashVersionV1: return TxErrorMessages.InvalidBlobVersionedHashVersion;
   222→            }
   223→        }
   224→
   225→        return ValidationResult.Success;
   226→    }
   227→
   228→    internal static ValidationResult ValidateBlobGasLimits(int txBlobCount, IReleaseSpec spec)
   229→    {
   230→        if (txBlobCount < Eip4844Constants.MinBlobsPerTransaction)
   231→        {
   232→            return TxErrorMessages.BlobTxMissingBlobs;
   233→        }
   234→
   235→        ulong txBlobGas = BlobGasCalculator.CalculateBlobGas(txBlobCount);
   236→
   237→        ulong maxBlobGasPerBlock = spec.GetMaxBlobGasPerBlock();
   238→
   239→        if (txBlobGas > maxBlobGasPerBlock)
   240→        {
   241→            return BlockErrorMessages.BlobGasUsedAboveBlockLimit(maxBlobGasPerBlock, txBlobCount, txBlobGas);
   242→        }
   243→
   244→        ulong maxBlobGasPerTx = spec.GetMaxBlobGasPerTx();
   245→
   246→        return txBlobGas > maxBlobGasPerTx ? TxErrorMessages.BlobTxGasLimitExceeded(txBlobGas, maxBlobGasPerTx) : ValidationResult.Success;
   247→    }
   248→}
   249→
   250→public sealed class MaxBlobCountBlobTxValidator : ITxValidator
   251→{
   252→    public static readonly MaxBlobCountBlobTxValidator Instance = new();
   253→    private MaxBlobCountBlobTxValidator() { }
   254→
   255→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   256→        transaction switch
   257→        {
   258→            { Type: not TxType.Blob } => ValidationResult.Success,
