     4→using System;
     5→using System.Collections.Generic;
     6→using Nethermind.Int256;
     7→
     8→namespace Nethermind.Core.Specs
     9→{
    10→    /// <summary>
    11→    /// https://github.com/ethereum/EIPs
    12→    /// </summary>
    13→    public interface IReleaseSpec : IEip1559Spec, IReceiptSpec
    14→    {
    15→        public string Name { get; }
    16→        long MaximumExtraDataSize { get; }
    17→        long MaxCodeSize { get; }
    18→        //EIP-3860: Limit and meter initcode
    19→        long MaxInitCodeSize => 2 * MaxCodeSize;
    20→        long MinGasLimit { get; }
    21→        long MinHistoryRetentionEpochs { get; }
    22→        long GasLimitBoundDivisor { get; }
    23→        UInt256 BlockReward { get; }
    24→        long DifficultyBombDelay { get; }
    25→        long DifficultyBoundDivisor { get; }
    26→        long? FixedDifficulty { get; }
    27→        int MaximumUncleCount { get; }
    28→
    29→        /// <summary>
    30→        /// ---
    31→        /// In chainspec - Ethash.Duration
    32→        /// </summary>
    33→        bool IsTimeAdjustmentPostOlympic { get; }
    34→
    35→        /// <summary>
    36→        /// Homestead contract creation via transaction cost set to 21000 + 32000 (previously 21000)
    37→        /// Failing init does not create an empty code contract
    38→        /// Difficulty adjustment changed
    39→        /// Transaction signature uniqueness (s-value has to be less or equal than than secp256k1n/2)
    40→        /// </summary>
    41→        bool IsEip2Enabled { get; }
    42→
